import { createServerFn } from "@tanstack/react-start"
import { desc } from "drizzle-orm"
import { db } from "@/db"
import { suppliers, type Supplier } from "@/db/schema"

/** Read every supplier, newest first. */
export const listSuppliers = createServerFn({ method: "GET" }).handler(
  async (): Promise<Array<Supplier>> =>
    db.select().from(suppliers).orderBy(desc(suppliers.id)).all(),
)

export type AddSupplierInput = { name: string; phone?: string; note?: string }

/** Add one supplier. Returns the row that was written. */
export const addSupplier = createServerFn({ method: "POST" })
  .validator((input: AddSupplierInput) => {
    const name = String(input?.name ?? "").trim()
    if (!name) throw new Error("A supplier name is required.")
    const phone = String(input?.phone ?? "").trim()
    const note = String(input?.note ?? "").trim()
    return { name, phone: phone || null, note: note || null }
  })
  .handler(async ({ data }): Promise<Supplier> => {
    const [row] = await db.insert(suppliers).values(data).returning()
    return row
  })

